{"compatibility":"minor","safety_note_md":"# SafeStan Safety Note

Compatibility: minor.

Protected data: `y_pos` and `log_y_pos_safestan`.

Generated files: `model_safe.stan`, `data_safe.json`.

Changes: vectorized the Bernoulli likelihood for `y_pos` so the protected variable is observed once as a plain top-level identifier. Replaced the conditional likelihood `log(y[n]) ~ normal(...)` for observations with `y_pos[n] == 1` by a top-level protected deterministic reshape `log_y_pos_safestan`, scored once with a vectorized normal likelihood. Added `N_pos_safestan`, deterministically equal to `sum(y_pos)`, to size that positive-outcome likelihood vector. In `data_safe.json`, `log_y_pos_safestan[k]` is `log(y[n_k])`, where `n_k` are the indices with `y_pos[n_k] == 1` in increasing order. These changes preserve the original target density for the supplied interface under the deterministic reshape.
","model_safe_stan":"functions {
  real quantile_user_defined(vector x, real p) {
    int n; // length of vector x
    real index; // integer index of p
    int lo; // lower integer cap of the index
    int hi; // higher integer cap of the index
    real h; // generated weight between the lo and hi
    real qs; // weighted average of x[lo] and x[hi]
    n = num_elements(x);
    index = 1 + (n - 1) * p;
    lo = 1;
    while ((lo + 1) < index) {
      lo = lo + 1;
    }
    hi = lo + 1;
    h = index - lo;
    qs = (1 - h) * sort_asc(x)[lo] + h * sort_asc(x)[hi];
    return qs;
  }
}
data {
  int<lower=0> N; // sample size
  int<lower=0> N_cov; // number of covariates
  array[N] real y; // continuous outcome
  array[N] int<lower=0, upper=1> y_pos; // indicator for y > 0
  array[N] int<lower=0, upper=1> z; // treatment assigned
  array[N] vector[N_cov] x; // covariates
  array[N] vector[N_cov] xz_inter; // interaction terms
  real<lower=-1, upper=1> rho; // assumed correlation between the potential outcomes
  int<lower=0, upper=N> N_pos_safestan; // deterministic sum(y_pos)
  vector[N_pos_safestan] log_y_pos_safestan; // deterministic log(y[n]) for y_pos[n] == 1
}
parameters {
  // Binary Sub-Model
  real alpha_bin; // intercept
  row_vector[N_cov] beta_bin; // coefficients for x[N]
  row_vector[N_cov] beta_inter_bin; // coefficients for x_inter[N] 
  real tau_bin; // treatment effect

  // Continuous Sub-Model
  real alpha_cont; // intercept       
  row_vector[N_cov] beta_cont; // coefficients for x[N]
  row_vector[N_cov] beta_inter_cont; // coefficients for x_inter[N]
  real tau_cont; // treatment effect for continuous part

  real<lower=0> sigma_t; // residual SD for the treated
  real<lower=0> sigma_c; // residual SD for the control
}
model {
  vector[N] eta_bin;
  vector[N_pos_safestan] mu_cont_pos;
  vector[N_pos_safestan] sigma_pos;
  int pos_safestan;

  // Priors for the Binary Sub-Model  
  alpha_bin ~ student_t(5, 0, 2.5); // student t with high df
  beta_bin ~ student_t(5, 0, 2.5);
  beta_inter_bin ~ student_t(5, 0, 2.5);
  tau_bin ~ student_t(5, 0, 2.5);

  // Priors for the Continuous Sub-Model       
  alpha_cont ~ normal(0, 100); // unscaled normal priors for coefficients
  beta_cont ~ normal(0, 100);
  beta_inter_cont ~ normal(0, 100);
  tau_cont ~ normal(0, 100);
  sigma_c ~ normal(0, 100);
  sigma_t ~ normal(0, 100);
  // sigma_c ~ inv_gamma(1, 0.01);          
  // sigma_t ~ inv_gamma(1, 0.01);

  // LIKELIHOOD
  for (n in 1 : N) {
    eta_bin[n] = alpha_bin + beta_bin * x[n] + beta_inter_bin * xz_inter[n]
                 + tau_bin * z[n];
  }
  y_pos ~ bernoulli_logit(eta_bin);

  pos_safestan = 1;
  for (n in 1 : N) {
    if (y_pos[n] == 1) {
      mu_cont_pos[pos_safestan] = alpha_cont + beta_cont * x[n]
                                  + beta_inter_cont * xz_inter[n]
                                  + tau_cont * z[n];
      sigma_pos[pos_safestan] = sigma_t * z[n] + sigma_c * (1 - z[n]);
      pos_safestan = pos_safestan + 1;
    }
  }
  log_y_pos_safestan ~ normal(mu_cont_pos, sigma_pos);
}
generated quantities {
  // finite sample average treatment effect (ATE) & mean values
  real y0_bar;
  real y1_bar;
  real tau_samp;

  // finite sample quantile treatment effects (QTEs)
  real tau_qte25;
  real tau_qte50;
  real tau_qte75;
  {
    // to create temporary variables
    // Generate science table
    array[N] real y0;
    array[N] real y1;
    array[N] real tau_ind; // individual treatment effects (ITE)

    // temporary variable for positive y_pred
    int y_pred_pos;
    for (n in 1 : N) {
      // Predicted chance of success: Binary part
      real theta_c = inv_logit(alpha_bin + beta_bin * x[n]);
      real theta_t = inv_logit(alpha_bin + beta_bin * x[n]
                               + beta_inter_bin * x[n] + tau_bin);

      // Predicted log mean: Continuous part
      real mu_c = alpha_cont + beta_cont * x[n];
      real mu_t = alpha_cont + beta_cont * x[n] + beta_inter_cont * x[n]
                  + tau_cont;

      if (z[n] == 1) {
        // (1) Impute Y_mis(0)    
        // Binary Sub-model: predict positive y_pred(0)
        y_pred_pos = bernoulli_rng(theta_c);
        if (y_pred_pos == 0) {
          y0[n] = 0;
        } else {
          y0[n] = exp(normal_rng(mu_c
                                 + rho * (sigma_c / sigma_t) * (y[n] - mu_t),
                                 sigma_c * sqrt(1 - rho ^ 2)));
        }
        // Fill in Y_obs(1)
        y1[n] = y[n];
      } else {
        // z[n] == 0,  (2) Impute Y_mis(1)    
        // Fill in Y_obs(0)
        y0[n] = y[n];

        // Binary Sub-model: predict positive y_pred(1)
        y_pred_pos = bernoulli_rng(theta_t);
        if (y_pred_pos == 0) {
          y1[n] = 0;
        } else {
          y1[n] = exp(normal_rng(mu_t
                                 + rho * (sigma_t / sigma_c) * (y[n] - mu_c),
                                 sigma_t * sqrt(1 - rho ^ 2)));
        }
      }
      tau_ind[n] = y1[n] - y0[n]; // generate ITE   
    } // end for loop

    // store mean values and ATE
    y0_bar = mean(y0);
    y1_bar = mean(y1);
    tau_samp = mean(tau_ind);

    // store QTEs
    tau_qte25 = quantile_user_defined(to_vector(y1), 0.25)
                - quantile_user_defined(to_vector(y0), 0.25);
    tau_qte50 = quantile_user_defined(to_vector(y1), 0.50)
                - quantile_user_defined(to_vector(y0), 0.50);
    tau_qte75 = quantile_user_defined(to_vector(y1), 0.75)
                - quantile_user_defined(to_vector(y0), 0.75);
  } // end temporary variables
}
","data_safe_json":"{"N":2,"N_cov":4,"rho":-0.1772897197614416,"x":[[6.727349060600306,5.1423975722891155,2.63483560586147,2.7206534432568015],[3.98179968207611,5.311467071208588,5.910332632403773,3.6138566473878337]],"xz_inter":[[4.792110045087956,6.160284103555384,4.155038614219705,5.734915001039128],[6.991124577455023,4.958062029259631,6.951185789698645,2.1004629654988034]],"y":[2.0,2.0],"y_pos":[1,1],"z":[1,1],"N_pos_safestan":2,"log_y_pos_safestan":[0.6931471805599453,0.6931471805599453]}","protected_variables":["y_pos","log_y_pos_safestan"]}
